def ref(xs):
    return sum(xs) / len(xs) if xs else None
def cand(xs):
    return max(xs) if xs else None
assert mismatches(cand, ref, [[1.0, 1.0], [1.0, 3.0]]) == [1]

def ref(xs):
    return sum(xs) / len(xs) if xs else None
def cand(xs):
    return sum(xs) / len(xs)
assert mismatches(cand, ref, [[2.0], []]) == [1]

def ref(xs):
    return 0.3
def cand(xs):
    return 0.1 + 0.2
assert mismatches(cand, ref, [[0.0]]) == []

def ref(xs):
    return None
def cand(xs):
    return 0.0
assert mismatches(cand, ref, [[]]) == [0]
